    /// <summary>Texto traduzido com {0}, {1}... preenchidos.</summary>
    string TrF(string key, params object[] args)
    {
        try { return string.Format(Tr(key), args); }
        catch (FormatException) { return Tr(key); }
    }

    /// <summary>Rótulo do atalho no idioma atual (só a palavra "Espaço" muda).</summary>
    string PresetLabel(int i) => Presets[i].Label.Replace("Espaço", Tr("key.space"));

    /// <summary>Só as frases cujo nome começa por um dos prefixos, em JSON, para dentro de uma página.</summary>
    Dictionary<string, string> Texts(params string[] prefixes) =>
        I18nResolve(LangCode).Where(kv => prefixes.Any(p => kv.Key.StartsWith(p, StringComparison.Ordinal)))
            .ToDictionary(kv => kv.Key, kv => kv.Value);

    string TextsJson(params string[] prefixes) => JsonSerializer.Serialize(Texts(prefixes));

    /// <summary>Frases do painel (prefixo "p.").</summary>
    string PanelTextsJson() => TextsJson("p.");

    // O tipo de usuário é guardado em português no settings.json ("Ouvinte", "DJ / Produtor"...) para não
    // quebrar configurações antigas; aqui só se traduz o que aparece na tela.
    static readonly string[] BetaTypeKeys = { "ty.listener", "ty.dj", "ty.streamer", "ty.owner", "ty.other" };

    string TypeLabel(string stored)
    {
        var i = Array.IndexOf(BetaTypes, stored);
        return i >= 0 ? Tr(BetaTypeKeys[i]) : stored;
    }
}
